#' @title Process Data by Generating Missing Values
#'
#' @description For the `process_data`
#' argument. It introduces missing
#' values in the generated data.
#'
#' @details
#' This function is to be used in
#' the `process_data` argument of
#' [power4test()].
#'
#' The missing values are generated by
#' [mice::ampute()]. Please refer to
#' its help page, the vignette for
#' this function:
#' [Generate missing values with ampute](https://rianneschouten.github.io/mice_ampute/vignette/ampute.html),
#' and Schouten, Lugtig, and Vink (2018).
#'
#' In addition to `data`, only two
#' arguments are explicitly defined for
#' [missing_values()]: `prop` and `mech`.
#' The argument `prop` is defined to remind
#' users of the default value for this
#' argument. The argument `mech`, specifying
#' the missing data mechanism, is
#' defined because its default value
#' is different from that of [mice::ampute()].
#' For [missing_values()], the default value
#' is `"MCAR"`, missing completely at
#' random.
#'
#' Please refer to the help page of
#' [mice::ampute()] for other available
#' arguments.
#'
#' ## Note for `patterns` and other arguments with variable names
#'
#' If arguments such as `patterns` are
#' specified, the variable names need to be
#' those in the generated data. If
#' indicator scores are generated, the
#' names need to be the names of the indicators,
#' not the names of the latent variables.
#'
#' @return
#' It returns a data frame with the
#' missing values inserted.
#'
#' @param data A data frame.
#'
#' @param var_patterns A list
#' of named list. Used to specify the pattern
#' at the latent variable level. Each
#' list has two elements. `vars` is the
#' vector of latent variables names. The
#' pattern will consist of all indicators
#' of these latent variables.
#' `prop` is the proportion of missing
#' for this pattern. If the values of
#' `prop` summed to one, then the values
#' will be used as `freq` in [mice::ampute()].
#' If they do not summed to one and `prop`
#' is not set manually, the sum will be
#' used in `prop`, and `prop` divided by the
#' sum will be used as `freq`.
#'
#' @param vars_in_waves A list of character
#' vectors. Each vector denotes the
#' latent variables or non-indicator
#' observed variables in a wave.
#' For example,
#' `list("x", c("m1", "m2"), "y")` means
#' that `x` is collected in Wave 1,
#' `m1` and `m2` in Wave 2, and `y` in
#' Wave 3.
#'
#' @param attrition_rate The probability
#' that a case will drop out from one
#' wave to another.
#'
#' @param ... Optional arguments to be
#' passed to [mice::ampute()].
#'
#' @param prop The proportion of missingness.
#' Default is 0.5, about 50% of the cases
#' have missing data.
#' If set to `NULL`,
#' then the original data (`data`) will
#' be returned unchanged.
#'
#' @param mech The missing data mechanism.
#' Default is `"MCAR"` (missing completely at random).
#' Other possible values are `"MAR"`
#' (missing at random) and `"MNAR"`
#' (missing not at random). Please refer
#' to the help of [mice::ampute()] for
#' details.
#'
#' @seealso [power4test()]. See also
#' [mice::ampute()] for the amputation
#' method.
#'
#' @references
#' Schouten, R. M., Lugtig, P., & Vink, G.
#' (2018). Generating missing values for
#' simulation purposes: A multivariate
#' amputation procedure.
#' *Journal of Statistical Computation and Simulation, 88*(15),
#' 2909--2930. \doi{10.1080/00949655.2018.1491577}
#'
#' @examples
#'
#' # Specify the model
#'
#' mod <-
#' "
#' m ~ x
#' y ~ m + x
#' "
#'
#' # Specify the population values
#'
#' mod_es <-
#' "
#' y ~ m: l
#' m ~ x: m
#' y ~ x: n
#' "
#' # Simulate the data
#'
#' out <- power4test(
#'          nrep = 2,
#'          model = mod,
#'          pop_es = mod_es,
#'          n = 200,
#'          process_data = list(fun = "missing_values",
#'                              args = list(prop = .75)),
#'          test_fun = test_parameters,
#'          test_args = list(op = "~"),
#'          parallel = FALSE,
#'          iseed = 1234)
#'
#' dat <- pool_sim_data(out)
#' head(dat, 50)
#'
#' @export
missing_values <- function(
  data,
  ...,
  var_patterns = NULL,
  vars_in_waves = NULL,
  attrition_rate = NULL,
  prop = 0.5,
  mech = "MCAR"
) {
  if (is.null(prop) &&
      is.null(var_patterns) &&
      is.null(vars_in_waves)) {
    return(data)
  }
  my_call <- match.call()
  args0 <- list(...)
  cnames <- colnames(data)
  if (!is.null(var_patterns) &&
      !is.null(args0$patterns)) {
    stop("var_patterns and patterns cannot be used together.")
  }
  if (!is.null(vars_in_waves) &&
      !is.null(args0$patterns)) {
    stop("vars_in_waves and patterns cannot be used together.")
  }
  if (!is.null(vars_in_waves) &&
      !is.null(var_patterns)) {
    stop("vars_in_waves and var_patterns cannot be used together.")
  }

  if (!is.null(args0$patterns)) {
    args0$patterns <- args0$patterns[, cnames]
  }
  if (!is.null(args0$weights)) {
    if (!is.null(var_patterns)) {
      stop("weights cannot be used with var_patterns")
    }
    if (!is.null(vars_in_waves)) {
      stop("weights cannot be used with vars_in_waves")
    }
    args0$weights <- args0$weights[, cnames]
  }

  # ==== Handle vars_in_waves ====

  if (!is.null(vars_in_waves)) {
    # vars_in_waves set. Use it to generate
    # var_patterns
    if (is.null(attrition_rate)) {
      stop("attrition_rate must be set along with vars_in_waves.")
    }
    var_patterns <- from_attrition(
      vars_in_waves = vars_in_waves,
      attrition_rate = attrition_rate
    )
  }

  # ==== Handle var_patterns ====

  if (!is.null(var_patterns)) {
    my_patterns <- expand_var_patterns(
      data = data,
      var_patterns = var_patterns
    )
    my_prop <- sapply(
      var_patterns,
      \(x) x$prop
    )
    my_prop_sum <- sum(my_prop)
    my_prop_one <- all.equal(
      my_prop_sum,
      1
    )
    prop_set <- "prop" %in% names(my_call)
    if (isTRUE(my_prop_one)) {
      # my_prop is the vector of freq
      args0$freq <- my_prop
    } else {
      # my_prop is not a vector of proportions
      # Use as frequency
      args0$freq <- my_prop / my_prop_sum
      # Always override prop is not set
      prop <- my_prop_sum
    }
    args0$patterns <- my_patterns
  }

  args <- utils::modifyList(
            args0,
            list(data = data,
                 prop = prop,
                 mech = mech,
                 run = TRUE),
            keep.null = TRUE)
  out <- do.call(mice::ampute,
                 args)
  out$amp
}

#' @noRd
get_ind_names <- function(
  data
) {
  k_ind <- attr(data, "number_of_indicators")
  # ==== Any factors with indicators? ====
  if (isTRUE(is.null(k_ind)) ||
      (all(k_ind == 1))) {
    return(colnames(data))
  }
  f_names <- names(k_ind)
  f <- function(x, xk) {
    paste0(x, seq_len(xk))
  }
  ind_names <- mapply(
                FUN = f,
                x = f_names,
                xk = k_ind,
                SIMPLIFY = FALSE
              )
  f_no_ind <- setdiff(colnames(data), unlist(ind_names))
  ov_names <- as.list(f_no_ind)
  names(ov_names) <- ov_names
  out <- c(ind_names, ov_names)
  out
}

#' @noRd
expand_var_patterns <- function(
  data,
  var_patterns
) {
  ind_names <- get_ind_names(data)
  vnames <- colnames(data)
  p_base <- vector("numeric", ncol(data))
  p_base[] <- 1
  names(p_base) <- vnames
  out0 <- mapply(
    \(x, ind_names, p_base) {
      var_i <- x$vars
      ind_i <- unlist(ind_names[var_i])
      p_base[ind_i] <- 0
      p_base
    },
    x = var_patterns,
    MoreArgs = list(
      p_base = p_base,
      ind_names = ind_names
    ),
    SIMPLIFY = FALSE
  )
  out1 <- do.call(
    rbind,
    out0
  )
  out1 <- out1[, vnames]
  out1
}

#' @noRd

from_attrition <- function(
  vars_in_waves,
  attrition_rate
) {
  k <- length(vars_in_waves)
  patterns <- vector(
    "list",
    length = k
  )
  for (i in seq_len(k)) {
    patterns[[i]] <- unlist(vars_in_waves[i:k])
  }
  props <- vector("numeric", k)
  props[] <- NA
  stay_rate <- 1 - attrition_rate
  for (i in seq_len(k)) {
    props[i] <- stay_rate^(i - 2) * attrition_rate
  }
  props[1] <- stay_rate^(k - 1)
  props1 <- props[-1]
  patterns1 <- patterns[-1]
  out <- mapply(
    \(x, y) {
      list(vars = x, prop = y)
    },
    x = patterns1,
    y = props1,
    SIMPLIFY = FALSE
  )
  out
}
